const items = $input.all();
const maxProductsEnv = Number($env.SHOPIFY_MAX_PRODUCTS || 0);
const maxProducts = Number.isFinite(maxProductsEnv) && maxProductsEnv > 0 ? maxProductsEnv : 0;
const webpQuality = Number($env.WEBP_QUALITY || 80) || 80;

const outputs = [];
let processedProducts = 0;

for (const item of items) {
  const product = item.json || {};
  if (!product.id) continue;

  processedProducts += 1;
  if (maxProducts && processedProducts > maxProducts) break;

  const images = Array.isArray(product.images) ? product.images : [];
  for (const image of images) {
    if (!image || !image.id || !image.src) continue;
    outputs.push({
      json: {
        productId: product.id,
        productHandle: product.handle || '',
        productTitle: product.title || '',
        imageId: image.id,
        imageSrc: image.src,
        imageAlt: image.alt || '',
        webpQuality,
        originalFormat: null,
        message: null,
        isAnimated: false
      }
    });
  }
}

return outputs;

const sharp = require('sharp');
const items = $input.all();

return Promise.all(items.map(async (item) => {
  const imageData = item.binary?.original;

  if (!imageData?.data) {
    item.json.isAnimated = true;
    item.json.message = 'Missing binary payload';
    return item;
  }

  const buffer = Buffer.from(imageData.data, 'base64');
  const metadata = await sharp(buffer, { animated: true }).metadata();
  const animated = (metadata.pages || 1) > 1;
  item.json.isAnimated = animated;
  item.json.originalFormat = metadata.format || imageData.mimeType || null;

  if (animated) {
    item.json.message = `Animated image skipped (product ${item.json.productHandle || item.json.productId})`;
    return item;
  }

  const quality = Number(item.json.webpQuality || 80) || 80;
  const webpBuffer = await sharp(buffer, { animated: false }).webp({ quality }).toBuffer();
  const fileNameBase = item.json.productHandle || item.json.productId || 'image';

  item.binary = item.binary || {};
  item.binary.webp = {
    data: webpBuffer.toString('base64'),
    mimeType: 'image/webp',
    fileName: `${fileNameBase}-${item.json.imageId}.webp`
  };
  item.json.webpSizeBytes = webpBuffer.length;
  item.json.message = `Converted image ${item.json.imageId} to WebP (${webpBuffer.length} bytes)`;
  return item;
}));

const items = $input.all();
return items.map(item => ({
  json: {
    status: 'skipped',
    reason: 'animated',
    productId: item.json.productId,
    imageId: item.json.imageId,
    message: item.json.message || 'Animated image skipped',
    productHandle: item.json.productHandle
  }
}));

const items = $input.all();
return items.map(item => ({
  json: {
    status: 'updated',
    productId: item.json.productId,
    imageId: item.json.imageId,
    productHandle: item.json.productHandle,
    message: item.json.message || 'Converted to WebP and uploaded',
    webpSizeBytes: item.json.webpSizeBytes
  }
}));
